let lastCloudBackupPricingFetchAt = 0;
const CLOUD_BACKUP_PRICING_MIN_REFRESH_INTERVAL_MS = 60 * 1000; 
async function fetchCloudBackupPricing() {
    if (!RELAY_API_KEY) return; 
    lastCloudBackupPricingFetchAt = Date.now();
    try {
        const installationId = getOrCreateInstallationId(readFeatureUnlocks());
        const relayRes = await relayFetch(`${RELAY_URL}/relay/pricing?installationId=${encodeURIComponent(installationId)}`, {
            headers: { 'x-relay-key': RELAY_API_KEY }
        }, 15000);
        if (!relayRes.ok) {
            console.warn(`⚠️  Hindi na-fetch ang Cloud Backup pricing mula RELAY (HTTP ${relayRes.status}) — gagamitin ang huling cache/fallback.`);
            return;
        }
        const data = await relayRes.json();
        if (data && data.success && data.cloudBackupPlans) {
            applyCloudBackupPricingOverlay(data.cloudBackupPlans);
            saveCloudBackupPricingCache(data);
        }
        if (data && data.success && data.featureCatalog) {
            applyFeatureCatalogPricingOverlay(data.featureCatalog);
        }
        if (data && data.success && data.upgradeTiers) {
            applyUpgradeTierPricingOverlay(data.upgradeTiers);
        }
        if (data && data.success && data.moduleSubscriptions) {
            applyModuleSubscriptionPricingOverlay(data.moduleSubscriptions);
        }
        if (data && data.success && data.aiSubscriptionPlans) {
            applyAiSubscriptionPlansOverlay(data.aiSubscriptionPlans);
        }
        if (data && data.success && typeof data.moduleSubscriptionGracePeriodDays !== 'undefined') {
            applyModuleSubscriptionGracePeriodOverlay(data.moduleSubscriptionGracePeriodDays);
        }
        if (data && data.success && typeof data.cloudBackupDataRetentionDays !== 'undefined') {
            applyCloudBackupRetentionDaysOverlay(data.cloudBackupDataRetentionDays);
        }
        if (data && data.success && data.activationFlags) {
            applyActivationFlagsOverlay(data.activationFlags);
        }
        if (data && data.success) {
            // An old RELAY without the support desk field means "closed".
            applySupportDeskOverlay(data.supportDesk || { open: false, message: '', updateSeq: '0' });
            onSupportDeskSignal();
        }
    } catch (err) {
        console.warn('⚠️  Hindi na-fetch ang Cloud Backup pricing mula RELAY (offline/timeout?) — gagamitin ang huling cache/fallback:', err.message);
    }
}
