const relayRemoteOperationsStatus = {
    state: 'orange',
    lastAttemptAt: null,
    lastSuccessAt: null,
    lastError: null,
    featureLocked: true
};
function computeRemoteOperationsPayload() {
    const rawTransactions = readData(FILE_TRANSACTIONS, []);
    const transactions = Array.isArray(rawTransactions) ? rawTransactions : [];
    const todayKey = getAttendanceDateKey(new Date());
    let todaySales = 0;
    let todayTransactions = 0;
    const dated = [];
    transactions.forEach((transaction, index) => {
        if (!transaction) return;
        const at = new Date(transaction.isoDate || transaction.timestamp || transaction.date || 0).getTime();
        if (!Number.isFinite(at) || at <= 0) return;
        const gross = Math.max(0, Number(transaction.total) || 0);
        const refunded = transaction.refundStatus === 'full'
            ? gross
            : Math.min(gross, Math.max(0, Number(transaction.totalRefunded) || 0));
        const net = Math.max(0, gross - refunded);
        if (getAttendanceDateKey(new Date(at)) === todayKey) {
            // Net of refunds, same rule as computeBranchSummaryPayload(), so both screens agree.
            todaySales += net;
            if (net > 0.009) todayTransactions += 1;
        }
        dated.push({ transaction, at, gross, index });
    });
    const nowMs = Date.now();
    const activeStaff = new Set();
    // Roster of today's attendance, shared cross-branch (via the encrypted Remote Operations
    // check-in) so an admin with the "remoteops" permission can see who's clocked in at OTHER
    // branches too, not just this one. Selfie photos themselves are never sent to RELAY — only
    // whether one was captured (hasSelfieIn/hasSelfieOut) — to keep this payload small and to
    // avoid shipping biometric-adjacent images off the device that took them.
    const attendanceRoster = [];
    getAttendanceRecords().forEach((record) => {
        if (!record) return;
        const isActive = !record.timeOutAt && !isAttendanceSessionStale(record, nowMs);
        if (isActive) activeStaff.add(attendanceUsernameKey(record.username));
        const recordDateKey = record.dateKey || getAttendanceSelfieDayKey(record);
        if (recordDateKey !== todayKey && !isActive) return; // keep it to "today" plus any still-open session
        attendanceRoster.push({
            id: String(record.id || ''),
            displayName: String(record.displayName || record.username || 'Unknown'),
            role: String(record.role || ''),
            timeInAt: record.timeInAt || null,
            timeOutAt: record.timeOutAt || null,
            autoClosed: !!record.autoClosed,
            hasSelfieIn: !!record.timeInSelfie,
            hasSelfieOut: !!record.timeOutSelfie
        });
    });
    attendanceRoster.sort((a, b) => new Date(b.timeInAt || 0) - new Date(a.timeInAt || 0));
    if (attendanceRoster.length > 50) attendanceRoster.length = 50;
    const recentTransactions = dated
        .sort((a, b) => b.at - a.at)
        .slice(0, 25)
        .map(({ transaction, at, gross, index }) => ({
            id: String(transaction.id || transaction.transactionId || transaction.isoDate || `transaction-${index}`),
            cashier: String(transaction.cashier || transaction.username || 'Unknown'),
            total: gross,
            paymentMethod: String(transaction.paymentMethod || transaction.payment || ''),
            at
        }));
    return {
        activeStaffCount: activeStaff.size,
        todaySales: Math.round(todaySales * 100) / 100,
        todayTransactions,
        recentTransactions,
        attendanceRoster
    };
}
let relayRemoteOperationsInFlight = false;
async function runRelayRemoteOperationsCheckin() {
    if (relayRemoteOperationsInFlight) return;
    relayRemoteOperationsInFlight = true;
    lastRemoteOperationsCheckinStartedAt = Date.now();
    try {
        await runRelayRemoteOperationsCheckinInner();
    } finally {
        relayRemoteOperationsInFlight = false;
    }
}
async function runRelayRemoteOperationsCheckinInner() {
    const featureUnlocked = getUnlockedFeatureIds().includes('remote_operations');
    relayRemoteOperationsStatus.featureLocked = !featureUnlocked;
    if (!featureUnlocked) return;
    const storeSettings = getStoreSettingsPublic(readData(FILE_STORE_SETTINGS, DEFAULT_STORE_SETTINGS));
    const groupKeyHash = hashBranchGroupKey(storeSettings.branchGroupKey);
    if (!groupKeyHash) {
        relayRemoteOperationsStatus.state = 'orange';
        relayRemoteOperationsStatus.lastError = 'No Business Group Code has been set — remote monitoring cannot check in yet.';
        return;
    }
    if (getConnectivityMode() === 'offline') {
        relayRemoteOperationsStatus.state = 'orange';
        relayRemoteOperationsStatus.lastError = 'Currently in OFFLINE mode — intentionally not calling the Relay for now.';
        return;
    }
    if (!RELAY_API_KEY) {
        relayRemoteOperationsStatus.state = 'orange';
        relayRemoteOperationsStatus.lastError = 'No RELAY_API_KEY configured — cannot check in to the Relay.';
        return;
    }
    relayRemoteOperationsStatus.lastAttemptAt = Date.now();
    try {
        const installationId = getOrCreateInstallationId(readFeatureUnlocks());
        // Blind relay: RELAY only ever sees an opaque, authenticated ciphertext blob for the
        // attendance/sales snapshot below. Only devices that know the same raw Business Group
        // Code can decrypt it (see decryptForGroup / decorateRemoteOperationsSummary).
        const encryptedRemoteOperations = encryptForGroup(computeRemoteOperationsPayload(), storeSettings.branchGroupKey);
        if (!encryptedRemoteOperations) {
            relayRemoteOperationsStatus.state = 'orange';
            relayRemoteOperationsStatus.lastError = 'Could not encrypt the remote operations check-in payload.';
            return;
        }
        const relayRes = await relayFetch(`${RELAY_URL}/relay/remote-operations/checkin`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'x-relay-key': RELAY_API_KEY },
            body: JSON.stringify({
                installationId,
                branchGroupKeyHash: groupKeyHash,
                branchName: storeSettings.branchName || null,
                encryptedRemoteOperations
            })
        });
        const relayData = await parseRelayResponse(relayRes);
        if (!relayData.success) {
            relayRemoteOperationsStatus.state = 'orange';
            relayRemoteOperationsStatus.lastError = relayData.message || 'The Relay rejected the remote operations check-in.';
            return;
        }
        relayRemoteOperationsStatus.state = 'green';
        relayRemoteOperationsStatus.lastSuccessAt = Date.now();
        relayRemoteOperationsStatus.lastError = null;
    } catch (err) {
        relayRemoteOperationsStatus.state = 'orange';
        relayRemoteOperationsStatus.lastError = err.message;
    }
}
