// FIX (two-sided stock movement): previously, "Accept"/"Reject" only
// updated the status on RELAY (RELAY has no access to the real
// Products/Inventory of any branch — each one has its own separate
// database). That meant even after "Accept", no real quantity actually
// changed — it still had to be done manually (Restock/Adjustment).
// Now, two new steps have been added AFTER "accepted":
//   1. "send"    — done by the SOURCE branch ("Mark as Sent"): deducts
//                  the item's stock in its own Products list here before
//                  updating the status on RELAY to "in_transit".
//   2. "receive" — done by the DESTINATION branch ("Confirm Received"):
//                  adds the item's stock to its own Products list here
//                  before updating the status on RELAY to "completed".
// So the real quantity change always happens on the device performing the
// action (its own local database), not on RELAY — RELAY only keeps the
// status in sync/consistent on both sides. Both are protected by
// transactionsMutexRunExclusive (the same mutex used by sale/void/refund/
// restock) so this doesn't interleave with a concurrent change to
// FILE_PRODUCTS.
function findLocalProductForTransfer(products, sku, itemName) {
    const cleanSku = String(sku || '').trim().toLowerCase();
    if (cleanSku) {
        const bySku = products.find(p => String(p.code || '').trim().toLowerCase() === cleanSku);
        if (bySku) return bySku;
    }
    const cleanName = String(itemName || '').trim().toLowerCase();
    if (cleanName) {
        const byName = products.find(p => String(p.name || '').trim().toLowerCase() === cleanName);
        if (byName) return byName;
    }
    return null;
}
app.post('/api/branches/transfer-respond', requirePermission('branches'), requireFeature('multi_branch'), rateLimit('branches-transfer-respond', 30, 10 * 60 * 1000), async (req, res) => {
    await transactionsMutexRunExclusive(() => processBranchTransferRespond(req, res));
});
// Clears the FINISHED (completed/rejected/cancelled) transfer requests from
// the shared history on RELAY. Admin-only: this history is shared across
// the whole branch group (not per-device), so clearing it here also clears
// it for every other branch in the group — same reason it is intentionally
// left OUT of the local Hard Reset (Hard Reset only wipes this device's own
// local data; it never touches shared RELAY data belonging to other
// branches). Pending/accepted/in_transit transfers are never deleted here.
app.post('/api/branches/transfers/clear-history', requirePermission('branches'), requireFeature('multi_branch'), rateLimit('branches-transfer-clear', 10, 10 * 60 * 1000), async (req, res) => {
    if (!req.authUser || req.authUser.role.toLowerCase() !== 'admin') {
        return res.status(403).json({ success: false, message: 'Access Denied: Only Admin can clear the shared transfer history (it affects every branch in the group).' });
    }
    const storeSettings = getStoreSettingsPublic(readData(FILE_STORE_SETTINGS, DEFAULT_STORE_SETTINGS));
    const groupKeyHash = hashBranchGroupKey(storeSettings.branchGroupKey);
    if (!groupKeyHash) return res.status(400).json({ success: false, message: 'No Business Group Code has been configured yet.' });
    if (!RELAY_API_KEY) return res.status(500).json({ success: false, message: 'No RELAY_API_KEY configured in .env.' });
    try {
        const data = readFeatureUnlocks();
        const installationId = getOrCreateInstallationId(data);
        const relayRes = await relayFetch(`${RELAY_URL}/relay/branch-transfers/clear-finished`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'x-relay-key': RELAY_API_KEY },
            body: JSON.stringify({ installationId, branchGroupKeyHash: groupKeyHash })
        });
        const relayData = await parseRelayResponse(relayRes);
        if (!relayData.success) {
            return res.status(relayRes.status || 502).json({ success: false, message: relayData.message || 'The transfer history could not be cleared.' });
        }
        res.json({ success: true, clearedCount: relayData.clearedCount || 0, remainingCount: relayData.remainingCount || 0 });
    } catch (err) {
        res.status(502).json({ success: false, message: `Could not reach the relay: ${err.message}` });
    }
});
// Undoes a local stock change made for a branch transfer when RELAY did not accept the status change.
// If nothing else touched the product since, the exact before-state (stock + batches) is restored; otherwise the
// opposite operation is applied so any sale/restock that happened in between is NOT overwritten.
function rollbackBranchTransferStock(stockMutation) {
    if (!stockMutation) return;
    try {
        const rollbackProducts = readProductsNoImages();
        const rollbackProduct = rollbackProducts.find(p => String(p.code || '') === String(stockMutation.productCode || ''));
        if (!rollbackProduct) return;
        const untouched = Math.abs((parseFloat(rollbackProduct.stock) || 0) - (parseFloat(stockMutation.afterStock) || 0)) < 1e-6;
        if (untouched && stockMutation.snapshot) {
            rollbackProduct.stock = stockMutation.snapshot.stock;
            if (stockMutation.snapshot.batches) rollbackProduct.batches = stockMutation.snapshot.batches;
            else delete rollbackProduct.batches;
        } else if (stockMutation.op === 'out') {
            addBaseStock(rollbackProduct, stockMutation.qty);
        } else {
            deductProductStock(rollbackProduct, stockMutation.qty);
        }
        writeData(FILE_PRODUCTS, rollbackProducts);
    } catch (rollbackErr) { console.error('[branch-transfer] stock rollback failed:', rollbackErr); }
}
async function processBranchTransferRespond(req, res) {
    const storeSettings = getStoreSettingsPublic(readData(FILE_STORE_SETTINGS, DEFAULT_STORE_SETTINGS));
    const groupKeyHash = hashBranchGroupKey(storeSettings.branchGroupKey);
    if (!groupKeyHash) return res.status(400).json({ success: false, message: 'No Business Group Code has been configured yet.' });
    if (!RELAY_API_KEY) return res.status(500).json({ success: false, message: 'No RELAY_API_KEY configured in .env.' });
    const { transferId, action } = req.body || {};
    const username = req.authUser && req.authUser.username;
    // Declared OUTSIDE the try so the catch below can roll the local stock back too.
    let matchedProduct = null;
    let stockNote = '';
    let stockMutation = null;
    try {
        const data = readFeatureUnlocks();
        const installationId = getOrCreateInstallationId(data);
        // First fetch the transfer's current contents from RELAY (to get
        // itemName/sku/qty/direction) before making any local stock
        // change — this also avoids a double-apply if the button is
        // clicked repeatedly (RELAY is what enforces the correct status
        // sequence below).
        if (action === 'send' || action === 'receive') {
            // FIX: same missing installationId query param as fixed in
            // GET /api/branches/transfers above — this also caused a 403
            // from requireAllowedDevice on RELAY.
            const listRes = await relayFetch(`${RELAY_URL}/relay/branch-transfers?groupKeyHash=${encodeURIComponent(groupKeyHash)}&installationId=${encodeURIComponent(installationId)}`, {
                method: 'GET', headers: { 'x-relay-key': RELAY_API_KEY }
            });
            const listData = await parseRelayResponse(listRes);
            if (!listData.success) {
                return res.status(listRes.status || 502).json({ success: false, message: listData.message || 'Could not look up the transfer request.' });
            }
            const transfer = (listData.transfers || []).find(t => t.id === transferId);
            if (!transfer) return res.status(404).json({ success: false, message: 'Transfer request not found.' });
            if (action === 'send' && transfer.fromInstallationId !== installationId) {
                return res.status(403).json({ success: false, message: 'Only the source branch can mark this transfer as sent.' });
            }
            if (action === 'receive' && transfer.toInstallationId !== installationId) {
                return res.status(403).json({ success: false, message: 'Only the destination branch can confirm receipt of this transfer.' });
            }
            // BUGFIX: a missing/zero/negative/non-numeric qty from the relay made `stock - qty` NaN (or ADDED stock on a
            // "send"), corrupting the product's stock. Reject it before touching anything.
            const transferQty = uomPricing.round(parseFloat(transfer.qty), uomPricing.DECIMAL_PLACES);
            if (!isFinite(transferQty) || transferQty <= 0) {
                return res.status(400).json({ success: false, message: 'This transfer has an invalid quantity, so no stock was changed.' });
            }
            transfer.qty = transferQty;
            let products = readProductsNoImages();
            matchedProduct = findLocalProductForTransfer(products, transfer.sku, transfer.itemName);
            if (action === 'send') {
                if (!matchedProduct) {
                    stockNote = ` (no matching product found here for SKU/name "${transfer.sku || transfer.itemName}" — stock was not deducted, adjust manually if needed)`;
                } else {
                    const currentStock = parseFloat(matchedProduct.stock) || 0;
                    if (currentStock < transfer.qty) {
                        return res.status(409).json({ success: false, message: `Not enough stock of "${matchedProduct.name}" here (only ${currentStock}, need ${transfer.qty}). Adjust the quantity or restock before marking as sent.` });
                    }
                    // BUGFIX: used `matchedProduct.stock = ...` directly, which desynced `batches` from `stock` on
                    // batch-tracked products (the change was then undone by the next sale). Use the shared helper.
                    const snapshot = { stock: matchedProduct.stock, batches: JSON.parse(JSON.stringify(matchedProduct.batches || null)) };
                    deductProductStock(matchedProduct, transfer.qty);
                    writeData(FILE_PRODUCTS, products);
                    stockMutation = { productCode: matchedProduct.code, op: 'out', qty: transfer.qty, snapshot, afterStock: matchedProduct.stock };
                    logAction(username, `Branch transfer OUT: -${transfer.qty} "${matchedProduct.name}" (new stock: ${matchedProduct.stock}) to ${transfer.toBranchName || 'another branch'} [transfer ${transferId}]`);
                }
            } else if (action === 'receive') {
                if (!matchedProduct) {
                    stockNote = ` (no matching product found here for SKU/name "${transfer.sku || transfer.itemName}" — stock was not added; create a new Product entry or adjust manually)`;
                } else {
                    const snapshot = { stock: matchedProduct.stock, batches: JSON.parse(JSON.stringify(matchedProduct.batches || null)) };
                    addBaseStock(matchedProduct, transfer.qty);
                    writeData(FILE_PRODUCTS, products);
                    stockMutation = { productCode: matchedProduct.code, op: 'in', qty: transfer.qty, snapshot, afterStock: matchedProduct.stock };
                    logAction(username, `Branch transfer IN: +${transfer.qty} "${matchedProduct.name}" (new stock: ${matchedProduct.stock}) from ${transfer.fromBranchName || 'another branch'} [transfer ${transferId}]`);
                }
            }
        }
        const relayRes = await relayFetch(`${RELAY_URL}/relay/branch-transfer-respond`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'x-relay-key': RELAY_API_KEY },
            body: JSON.stringify({ installationId, branchGroupKeyHash: groupKeyHash, transferId, action })
        });
        const relayData = await parseRelayResponse(relayRes);
        if (!relayData.success) {
            rollbackBranchTransferStock(stockMutation);
            return res.status(relayRes.status || 502).json({ success: false, rolledBack: !!stockMutation, message: relayData.message || 'The transfer request could not be updated.' });
        }
        res.json({ success: true, transfer: relayData.transfer, stockNote: stockNote || undefined });
    } catch (err) {
        // FIX: if the relay call itself threw (timeout / no internet / non-JSON reply) AFTER the
        // local stock was already deducted/added, that change was never undone — the transfer's
        // status stayed unchanged on RELAY, so pressing the button again applied the stock
        // change a SECOND time. Roll it back here, same as the "relay said no" path above.
        rollbackBranchTransferStock(stockMutation);
        res.status(502).json({ success: false, rolledBack: !!stockMutation, message: `Could not reach the relay: ${err.message}` });
    }
}
let integrityWatchDebounceTimer = null;
let integrityWatchLastRunAt = 0;
const INTEGRITY_WATCH_DEBOUNCE_MS = 800;
const INTEGRITY_WATCH_MIN_GAP_MS = 1500;
const integrityWatchers = new Map();
function scheduleIntegrityCheckinFromWatcher(changedPath) {
    if (integrityWatchDebounceTimer) clearTimeout(integrityWatchDebounceTimer);
    integrityWatchDebounceTimer = setTimeout(() => {
        integrityWatchDebounceTimer = null;
        const wait = Math.max(0, INTEGRITY_WATCH_MIN_GAP_MS - (Date.now() - integrityWatchLastRunAt));
        setTimeout(() => {
            integrityWatchLastRunAt = Date.now();
            runRelayIntegrityCheckin().catch(() => {});
        }, wait);
    }, INTEGRITY_WATCH_DEBOUNCE_MS);
}
function watchDirForIntegrity(dir) {
    if (integrityWatchers.has(dir)) return;
    try {
        const watcher = fs.watch(dir, { persistent: false }, (eventType, filename) => {
            scheduleIntegrityCheckinFromWatcher(filename ? path.join(dir, filename) : dir);
        });
        watcher.on('error', () => { integrityWatchers.delete(dir); });
        integrityWatchers.set(dir, watcher);
    } catch (err) {
    }
}
function refreshIntegrityWatchers() {
    function walk(dir) {
        let entries;
        try {
            entries = fs.readdirSync(dir, { withFileTypes: true });
        } catch (err) {
            return;
        }
        watchDirForIntegrity(dir);
        for (const entry of entries) {
            if (INTEGRITY_SCAN_EXCLUDE_NAMES.has(entry.name)) continue;
            if (entry.isDirectory()) walk(path.join(dir, entry.name));
        }
    }
    walk(__dirname);
}
if (!INTEGRITY_MONITOR_DISABLED) {
    setTimeout(refreshIntegrityWatchers, 10 * 1000);
    setInterval(refreshIntegrityWatchers, 5 * 60 * 1000).unref();
}
let integrityCheckNowInProgress = false;
const INTEGRITY_CHECK_NOW_POLL_MS = Number(process.env.RELAY_INTEGRITY_CHECK_NOW_POLL_MS) || 3 * 1000;
async function pollPendingIntegrityCheckNow() {
    if (!RELAY_API_KEY || getConnectivityMode() === 'offline') return;
    if (integrityCheckNowInProgress) return;
    if (!(await isInternetLikelyUp())) return;
    try {
        const data = readFeatureUnlocks();
        const installationId = getOrCreateInstallationId(data);
        const relayRes = await relayFetch(`${RELAY_URL}/relay/pending-integrity-check`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'x-relay-key': RELAY_API_KEY },
            body: JSON.stringify({ installationId })
        }, 8000);
        const relayData = await parseRelayResponse(relayRes);
        if (relayData.success && relayData.pending) {
            integrityCheckNowInProgress = true;
            try {
                await runRelayIntegrityCheckin();
            } finally {
                integrityCheckNowInProgress = false;
            }
        }
    } catch (err) {
    }
}
if (!INTEGRITY_MONITOR_DISABLED && RELAY_API_KEY) {
    setTimeout(pollPendingIntegrityCheckNow, 15 * 1000);
    setInterval(() => { pollPendingIntegrityCheckNow().catch(() => {}); }, INTEGRITY_CHECK_NOW_POLL_MS).unref();
}
