const cloudBackupStatus = {
    state: 'idle',
    lastAttemptAt: null,
    lastSuccessAt: null,
    lastError: null,
    lastTotalRecords: null,
    lastTrigger: null, 
    lastErrorWasRateLimited: false,
    lastSizeBytes: null,
    lastSizeMB: null,
    lastQuotaMB: null,
    lastPercentUsed: null,
    uploadStartedAt: null,
    uploadedBytes: null,
    uploadTotalBytes: null
};
function getCloudBackupSubscriptionInfo() {
    const data = readFeatureUnlocks();
    const installationId = getOrCreateInstallationId(data);
    const token = data.tokens[CLOUD_BACKUP_FEATURE_ID];
    const active = !!(token && verifyUnlockToken(token, installationId, CLOUD_BACKUP_FEATURE_ID));
    const expiresAt = (token && typeof token.payload.expiresAt === 'number') ? token.payload.expiresAt : null; 
    const plan = (data.cloudBackupPlan && CLOUD_BACKUP_PLANS[data.cloudBackupPlan.tier]) ? data.cloudBackupPlan : null;
    const info = {
        active,
        expiresAt,
        tier: plan ? plan.tier : (active ? 'basic' : null), 
        billingCycle: plan ? plan.billingCycle : null,
        isLegacyLifetime: active && expiresAt === null && !plan
    };
    // BAGO: kapag inactive/expired na ang subscription (hindi Lifetime),
    // ibinabalik din dito ang retention countdown papunta sa PERMANENTENG
    // pagbura ng backup data ng installation na ito sa Neon (tingnan ang
    // CLOUD_BACKUP_DATA_RETENTION_DAYS/applyCloudBackupRetentionDaysOverlay
    // sa itaas, at ang runCloudBackupRetentionAutoPurgeSweep sa RELAY side
    // na aktwal na nagpapatupad nito) — ginagamit ito ng OMNIPOS client
    // (Settings > Cloud Backup) para ipakita ang "Your backed-up data will
    // be permanently deleted in Xd" na babala.
    if (!active && !info.isLegacyLifetime && typeof expiresAt === 'number') {
        const dataDeletionAt = expiresAt + (CLOUD_BACKUP_DATA_RETENTION_DAYS * 24 * 60 * 60 * 1000);
        info.retentionDays = CLOUD_BACKUP_DATA_RETENTION_DAYS;
        info.dataDeletionAt = dataDeletionAt;
        info.daysUntilDataDeletion = Math.ceil((dataDeletionAt - Date.now()) / (24 * 60 * 60 * 1000));
    }
    return info;
}
async function fetchCloudBackupLiveUsage(installationId) {
    if (!RELAY_API_KEY) return null;
    try {
        const relayRes = await relayFetch(
            `${RELAY_URL}/relay/cloud-backup/usage?installationId=${encodeURIComponent(installationId)}`,
            { method: 'GET', headers: { 'x-relay-key': RELAY_API_KEY } }
        );
        const relayData = await parseRelayResponse(relayRes);
        if (relayData && relayData.success && relayData.hasBackup) {
            return {
                sizeBytes: relayData.sizeBytes,
                sizeMB: relayData.sizeMB,
                sizeGB: relayData.sizeGB,
                tier: relayData.tier,
                quotaMB: relayData.quotaMB,
                percentUsed: relayData.percentUsed,
                nearQuota: !!relayData.nearQuota
            };
        }
    } catch (err) {
    }
    return null;
}
async function fetchCloudBackupCostShare(installationId) {
    if (!RELAY_API_KEY) return { success: false, message: 'RELAY_API_KEY is not configured.' };
    try {
        const relayRes = await relayFetch(
            `${RELAY_URL}/relay/cloud-backup/cost-allocation?installationId=${encodeURIComponent(installationId)}`,
            { method: 'GET', headers: { 'x-relay-key': RELAY_API_KEY } }
        );
        const relayData = await parseRelayResponse(relayRes);
        return relayData || { success: false, message: 'No response from RELAY.' };
    } catch (err) {
        return { success: false, message: 'Could not fetch the cost share: ' + err.message };
    }
}
app.get('/api/cloud-backup/status', async (req, res) => {
    const subscription = getCloudBackupSubscriptionInfo();
    let liveUsage = null;
    if (subscription.active) {
        liveUsage = await fetchCloudBackupLiveUsage(getOrCreateInstallationId(readFeatureUnlocks()));
        if (liveUsage) {
            cloudBackupStatus.lastSizeBytes = liveUsage.sizeBytes;
            cloudBackupStatus.lastSizeMB = liveUsage.sizeMB;
            cloudBackupStatus.lastQuotaMB = liveUsage.quotaMB;
            cloudBackupStatus.lastPercentUsed = liveUsage.percentUsed;
        }
    }
    res.json({
        success: true,
        ...cloudBackupStatus,
        storageUsage: liveUsage || (cloudBackupStatus.lastSizeBytes != null
            ? {
                sizeBytes: cloudBackupStatus.lastSizeBytes,
                sizeMB: cloudBackupStatus.lastSizeMB,
                quotaMB: cloudBackupStatus.lastQuotaMB,
                percentUsed: cloudBackupStatus.lastPercentUsed
              }
            : null),
        subscription
    });
});
