app.post('/api/ai-assistant/ask', requireAiAssistantOrFree(), rateLimit('ai-assistant-ask', 20, 5 * 60 * 1000, (retryAfterSec) => `Too many questions to Omni AI. Please try again after ${retryAfterSec} seconds.`), async (req, res) => {
    if (!isAiAssistantConfigured()) {
        return res.status(503).json({ success: false, message: 'Omni AI is not configured on this server yet (RELAY_API_KEY is required in .env; in the developer RELAY/.env: CF_ACCOUNT_ID/CF_AI_API_TOKEN for the Free plan and GOOGLE_AI_API_KEY for Base/Plus/Pro). Please contact the developer/admin.' });
    }
    const question = typeof req.body?.question === 'string' ? req.body.question.trim().slice(0, 800) : '';
    const lang = req.body?.lang === 'tl' ? 'tl' : 'en'; // Eng/Tag toggle: default English, Tagalog when the user picks it
    const rawContext = Array.isArray(req.body?.context) ? req.body.context : [];
    if (!question) {
        return res.status(400).json({ success: false, message: 'Missing question.' });
    }
    // BAGO: maraming attachment kada tanong. Tumatanggap ng `images` (array ng data URL, max 4) at
    // `files` (array ng {data, name}, max 3). Tinatanggap pa rin ang dating single `image` / `file` + `fileName`.
    const AI_MAX_IMAGES = 4;
    const AI_MAX_FILES = 3;
    const imageDataUrls = [];
    if (Array.isArray(req.body?.images)) {
        for (const x of req.body.images) {
            if (imageDataUrls.length >= AI_MAX_IMAGES) break;
            if (typeof x === 'string' && x.startsWith('data:image/')) imageDataUrls.push(x);
        }
    }
    if (!imageDataUrls.length && typeof req.body?.image === 'string' && req.body.image.startsWith('data:image/')) {
        imageDataUrls.push(req.body.image);
    }
    const attachedFiles = [];
    if (Array.isArray(req.body?.files)) {
        for (const f of req.body.files) {
            if (attachedFiles.length >= AI_MAX_FILES) break;
            if (f && typeof f.data === 'string' && f.data.startsWith('data:')) {
                attachedFiles.push({ data: f.data, name: typeof f.name === 'string' ? f.name.slice(0, 200) : '' });
            }
        }
    }
    if (!attachedFiles.length && typeof req.body?.file === 'string' && req.body.file.startsWith('data:')) {
        attachedFiles.push({ data: req.body.file, name: typeof req.body?.fileName === 'string' ? req.body.fileName.slice(0, 200) : '' });
    }
    const imageDataUrl = imageDataUrls[0] || null;
    const fileDataUrl = attachedFiles.length ? attachedFiles[0].data : null;
    if (req.aiFreeTier && (imageDataUrls.length || attachedFiles.length)) {
        return res.status(402).json({ success: false, freeTierLimit: true, message: 'The Omni AI Free plan is text-only. Subscribe to Omni AI (Base/Plus/Pro) to attach images or files.' });
    }
    if (imageDataUrls.some((u) => u.length > 6 * 1024 * 1024)) {
        return res.status(413).json({ success: false, message: 'The attached screenshot is too large. Please attach a smaller one (max ~4MB).' });
    }
    const fileContextMsgs = [];
    for (const att of attachedFiles) {
        const extraction = await extractTextFromAttachedDocument(att.data, att.name);
        if (!extraction.success) {
            return res.status(422).json({ success: false, message: extraction.message });
        }
        fileContextMsgs.push({
            role: 'system',
            content: `The user attached a document named "${att.name || 'attachment'}". Extracted text content (may be partial/truncated):\n\n${extraction.text || '(No readable text found in the document.)'}\n\nUse this only if relevant to the question; do not assume anything about the document beyond this extracted text.`
        });
    }

    const context = rawContext.slice(0, 8).map((c) => ({
        question: typeof c?.question === 'string' ? c.question.slice(0, 300) : '',
        answer: typeof c?.answer === 'string' ? c.answer.slice(0, 1200) : ''
    })).filter((c) => c.question || c.answer);
    const contextText = context.length
        ? context.map((c, i) => `[${i + 1}] Q: ${c.question}\nA: ${c.answer}`).join('\n\n')
        : '(No matching FAQ entries were found for this question.)';
    const rawHistory = Array.isArray(req.body?.history) ? req.body.history : [];
    const history = rawHistory.slice(-6).map((h) => ({
        role: h && h.role === 'assistant' ? 'assistant' : 'user',
        content: typeof h?.text === 'string' ? h.text.slice(0, 500) : ''
    })).filter((h) => h.content);
    const diagnosticMsg = buildDiagnosticSystemMessage(req.body?.diagnostics, req.body?.clientErrors);
    const userRole = req.authUser && req.authUser.role;
    const isAdminRole = (userRole || '').toLowerCase() === 'admin';
    const dbContextMsg = await buildAiDatabaseContextMessage(userRole, question);
    const dbContextMsgs = dbContextMsg ? (Array.isArray(dbContextMsg) ? dbContextMsg : [dbContextMsg]) : [];
    // BAGO: kapag ang tanong ay tungkol sa premium feature na hindi pa nabibili
    // sa store na ito, sabihan ang AI na magdagdag ng maikling paalala (ang
    // shortcut button naman ay lock/purchase modal ang bubuksan, hindi ang page).
    const lockedFeatureMsgs = [];
    try {
        const lockedHits = computeSuggestedActions(question, '', isAdminRole).filter((x) => x.locked);
        if (lockedHits.length) {
            const seenLocked = new Set();
            const lockedLines = [];
            for (const h of lockedHits) {
                if (seenLocked.has(h.featureId)) continue;
                seenLocked.add(h.featureId);
                lockedLines.push(`- "${h.featureName}" (${h.isSubscription ? 'monthly/yearly subscription' : 'one-time unlock purchase'})`);
            }
            lockedFeatureMsgs.push({
                role: 'system',
                content: 'LOCKED FEATURES NOTE (from the server, factual): the user\'s question touches the following premium feature(s) that are NOT yet purchased/activated on this store:\n' + lockedLines.join('\n') + '\nStill answer what the feature is/does using the context, but ALSO add ONE short reminder sentence that this feature is not yet activated in this store and needs a purchase/subscription first, and that the lock shortcut button under your answer opens the purchase options (it does NOT open the page directly). Do not give step-by-step instructions as if they could already use it, and never invent prices — the purchase window shows the real price.'
            });
        }
    } catch (e) { /* hindi dapat mabigo ang sagot dahil sa paalalang ito */ }
    const baseMessages = [
        { role: 'system', content: buildAiAssistantSystemPrompt(lang, isAdminRole) },
        { role: 'system', content: `OmniPOS FAQ Knowledge Base entries relevant to this question:\n\n${contextText}` },
        ...lockedFeatureMsgs,
        ...dbContextMsgs,
        ...fileContextMsgs,
        ...(diagnosticMsg ? [diagnosticMsg] : []),
        ...history
    ];
    const startedAt = Date.now();
    const username = (req.authUser && req.authUser.username) || 'Unknown';
    const requestId = crypto.randomUUID();
    // STOP: kapag pinindot ng user ang Stop (nag-disconnect ang browser), itigil ang request papuntang RELAY/Google.
    const aiAbort = new AbortController();
    res.on('close', () => { if (!res.writableFinished) aiAbort.abort(); });
    // Pinili ng user na Gemini model (kahit anong model na naka-enable sa RELAY) mula sa Omni AI Plans. Ang RELAY ang nagpapasya kung pinapayagan (tier/availability);
    // kapag hindi, awtomatiko itong babalik sa default provider ng RELAY.
    const aiModelChoice = (!req.aiFreeTier && typeof req.body?.model === 'string' && /^[A-Za-z0-9_-]{1,60}$/.test(req.body.model)) ? req.body.model : null;

    let result;
    let visionFailureReason = null;
    if (imageDataUrl) {
        const visionMessages = [
            ...baseMessages,
            {
                role: 'user',
                content: [
                    { type: 'text', text: question || (lang === 'tl' ? 'Ano ang nasa larawang ito at paano ito related sa OmniPOS?' : 'What is shown in this screenshot and how does it relate to OmniPOS?') },
                    ...imageDataUrls.map((u) => ({ type: 'image_url', image_url: { url: u } }))
                ]
            }
        ];
        result = await callCloudflareWorkersVisionAI(visionMessages, requestId, aiModelChoice, aiAbort.signal);
        if (result.cancelled || aiAbort.signal.aborted) return;
        if (!result.success) {
            visionFailureReason = result.message || 'Unknown vision error.';
            console.error(`⚠️ Omni AI vision call failed (falling back to text-only): ${visionFailureReason}`);
            result = await callCloudflareWorkersAI([...baseMessages, { role: 'user', content: `${question}\n\n(Note: the user attached a screenshot, but the image analysis failed on this attempt (temporary error, not a permanent limitation — you DO normally support screenshots). Briefly tell them the image could not be processed this time, ask them to press Try again or re-attach a clearer/smaller screenshot, and meanwhile ask them to describe what they see so you can still help.)` }], 'image', requestId, aiModelChoice, aiAbort.signal);
        }
    } else {
        result = await callCloudflareWorkersAI([...baseMessages, { role: 'user', content: question }], fileDataUrl ? 'file' : null, requestId, aiModelChoice, aiAbort.signal);
    }
    // Na-stop ng user: walang log, walang sagot na ipapadala (wala nang naghihintay) at hindi nasingil sa RELAY.
    if (result.cancelled || aiAbort.signal.aborted) return;

    const tookMs = Date.now() - startedAt;
    if (!result.success) {
        logAiAssistantInteraction({ username, question, lang, hasImage: !!imageDataUrl, hasFile: !!fileDataUrl, answered: false, tookMs, error: result.message, visionError: visionFailureReason || undefined });
        return res.status(result.statusCode || 502).json({ success: false, ...result, message: result.message });
    }

    const creditStatusAfter = result.credits || null;
    const suggestedActions = computeSuggestedActions(question, result.answer, isAdminRole);
    const usedLiveData = dbContextMsgs.length > 0 && questionLooksDataRelated(question) && /\d/.test(String(result.answer || ''));
    const interactionId = logAiAssistantInteraction({
        username, question, lang,
        hasImage: !!imageDataUrl, hasFile: !!fileDataUrl,
        answered: true, tookMs, creditCost: result.creditCost || 0,
        usedLiveData,
        answerPreview: String(result.answer || '').slice(0, 400),
        feedback: null,
        visionError: visionFailureReason || undefined
    });

    res.json({
        success: true,
        answer: result.answer,
        suggestedActions,
        credits: creditStatusAfter,
        interactionId,
        aiContext: { liveStoreData: usedLiveData }
    });
});
// BAGO: 👍/👎 feedback ng user sa sagot ng Omni AI. Dati, sa browser
// lang nakikita ang 👎 at ang 👍 ay hindi tinatala kahit saan — kaya walang
// paraan ang admin/developer para malaman kung gaano kakapaki-pakinabang
// ang mga sagot. Ang isang user ay puwede lang mag-vote sa sarili niyang
// interaction, at isang beses lang kada sagot.
app.post('/api/ai-assistant/feedback', requireAiAssistantOrFree(), rateLimit('ai-assistant-feedback', 60, 5 * 60 * 1000, (retryAfterSec) => `Too much feedback. Please try again after ${retryAfterSec} seconds.`), (req, res) => {
    const interactionId = typeof req.body?.interactionId === 'string' ? req.body.interactionId.slice(0, 60) : '';
    const vote = req.body?.vote === 'up' ? 'up' : (req.body?.vote === 'down' ? 'down' : null);
    if (!interactionId || !vote) {
        return res.status(400).json({ success: false, message: 'Missing interactionId or invalid vote.' });
    }
    const username = (req.authUser && req.authUser.username) || 'Unknown';
    try {
        const logs = readData(FILE_AI_ASSISTANT_LOGS, []);
        const entry = logs.find((l) => l && l.id === interactionId);
        if (!entry) {
            return res.status(404).json({ success: false, message: 'Interaction not found (maaaring luma na at natanggal na sa log).' });
        }
        if (entry.username !== username) {
            return res.status(403).json({ success: false, message: 'You cannot rate answers from other users.' });
        }
        if (entry.feedback) {
            return res.json({ success: true, alreadyRecorded: true });
        }
        entry.feedback = vote;
        entry.feedbackAt = new Date().toISOString();
        writeData(FILE_AI_ASSISTANT_LOGS, logs);
        return res.json({ success: true });
    } catch (err) {
        console.error('⚠️ Hindi na-save ang Omni AI feedback:', err);
        return res.status(500).json({ success: false, message: 'Hindi na-save ang feedback.' });
    }
});
// Reset Omni AI Insights (admin only): clears the question log and the 👍/👎 ratings.
app.delete('/api/ai-assistant/analytics', (req, res) => {
    if (!req.authUser || (req.authUser.role || '').toLowerCase() !== 'admin') {
        return res.status(403).json({ success: false, message: 'Admin access required.' });
    }
    try {
        // writeData() returns false (does not throw) when the DB write fails,
        // so check it — otherwise we would report success on a failed reset.
        if (writeData(FILE_AI_ASSISTANT_LOGS, []) === false) {
            return res.status(500).json({ success: false, message: 'Could not reset the insights.' });
        }
        logAction(req.authUser.username, 'Reset the Omni AI Insights (cleared question history and ratings)');
        return res.json({ success: true });
    } catch (err) {
        console.error('⚠️ Could not reset Omni AI insights:', err);
        return res.status(500).json({ success: false, message: 'Could not reset the insights.' });
    }
});
app.get('/api/ai-assistant/analytics', async (req, res) => {
    if (!req.authUser || (req.authUser.role || '').toLowerCase() !== 'admin') {
        return res.status(403).json({ success: false, message: 'Admin access required.' });
    }
    const logs = readData(FILE_AI_ASSISTANT_LOGS, []);
    const totalQuestions = logs.length;
    const answered = logs.filter((l) => l.answered).length;
    const withImage = logs.filter((l) => l.hasImage).length;
    const avgTookMs = totalQuestions ? Math.round(logs.reduce((sum, l) => sum + (l.tookMs || 0), 0) / totalQuestions) : 0;
    const questionCounts = {};
    logs.forEach((l) => {
        const key = (l.question || '').trim().toLowerCase();
        if (!key) return;
        questionCounts[key] = (questionCounts[key] || 0) + 1;
    });
    const topQuestions = Object.entries(questionCounts)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 10)
        .map(([question, count]) => ({ question, count }));
    // BAGO: answer-quality metrics mula sa 👍/👎 feedback ng mga user.
    const thumbsUp = logs.filter((l) => l.feedback === 'up').length;
    const thumbsDown = logs.filter((l) => l.feedback === 'down').length;
    const rated = thumbsUp + thumbsDown;
    const downCounts = {};
    logs.forEach((l) => {
        if (l.feedback !== 'down') return;
        const key = (l.question || '').trim().toLowerCase();
        if (!key) return;
        downCounts[key] = (downCounts[key] || 0) + 1;
    });
    const topDownvoted = Object.entries(downCounts)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 10)
        .map(([question, count]) => ({ question, count }));
    const unansweredRecent = logs.filter((l) => !l.answered).slice(0, 10).map((l) => ({ question: l.question, error: l.error, timestamp: l.timestamp }));
    let relayCredits = null;
    try {
        if (RELAY_API_KEY) {
            const installationId = getOrCreateInstallationId(readFeatureUnlocks());
            const relayRes = await relayFetch(`${RELAY_URL}/relay/ai-assistant/usage?installationId=${encodeURIComponent(installationId)}`, { method: 'GET', headers: { 'x-relay-key': RELAY_API_KEY } }, 10000);
            const relayData = await relayRes.json().catch(() => null);
            if (relayRes.ok && relayData?.success) relayCredits = relayData;
        }
    } catch (_) {}
    res.json({
        success: true,
        totalQuestions,
        answered,
        answerRate: totalQuestions ? Math.round((answered / totalQuestions) * 100) : 0,
        withImage,
        avgTookMs,
        topQuestions,
        thumbsUp,
        thumbsDown,
        helpfulRate: rated ? Math.round((thumbsUp / rated) * 100) : null,
        topDownvoted,
        unansweredRecent,
        recent: logs.slice(0, 50),
        credits: relayCredits
    });
});
// ---------------------------------------------------------------------
// SUPPORT TICKET <-> RELAY SYNC (RELAY-controlled, no polling)
// ---------------------------------------------------------------------
// Tickets are always saved locally first (works offline). RELAY controls when
// they are handled through the "support desk" switch:
//   - Desk CLOSED (default): new tickets stay queued locally and NOTHING is
//     sent to RELAY.
//   - Desk OPEN: queued tickets are forwarded (POST /relay/support-tickets,
//     idempotent by installationId + ticket id).
// The desk state arrives inside the /relay/pricing response that OMNIPOS
// already fetches (startup, every 30 minutes, and when the ticket list is
// opened), together with an "updateSeq" marker. Developer statuses/replies
// (GET /relay/support-tickets/status) are pulled ONLY when that marker
// differs from the last one processed, whether the desk is open or closed.
// There is no dedicated support timer.
let supportTicketSyncRerun = false; // a sync was requested while another was running -> run once more afterwards
const SUPPORT_TICKET_SYNC_DEADLINE_MS = 12000;
const SUPPORT_TICKET_SYNC_BATCH = 10;
const FILE_AI_SUPPORT_SYNC_STATE = 'aiSupportSyncState';
function sanitizeSupportTicketDiagnostics(raw) {
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null;
    const out = {};
    let count = 0;
    for (const [k, v] of Object.entries(raw)) {
        if (count >= 20) break;
        const key = String(k).slice(0, 60);
        if (typeof v === 'string') out[key] = v.slice(0, 300);
        else if (typeof v === 'number' && Number.isFinite(v)) out[key] = v;
        else if (typeof v === 'boolean') out[key] = v;
        else continue;
        count++;
    }
    return count ? out : null;
}
function supportTicketsPendingPush(tickets) {
    return tickets.some((t) => !t.relaySynced && !t.relaySyncFailed);
}
function readSupportSyncState() {
    const st = readData(FILE_AI_SUPPORT_SYNC_STATE, {});
    return (st && typeof st === 'object' && !Array.isArray(st)) ? st : {};
}
let supportTicketSyncPromise = null;
function syncSupportTicketsWithRelay(opts = {}) {
    if (!RELAY_API_KEY) return Promise.resolve({ skipped: true, reason: 'no_relay_key' });
    if (supportTicketSyncPromise) {
        // A sync is already running: ask for one more pass afterwards and let
        // the caller wait for the running one (so a freshly opened ticket list
        // shows up-to-date data instead of returning early).
        supportTicketSyncRerun = true;
        return supportTicketSyncPromise.catch(() => ({ skipped: true, reason: 'busy' }));
    }
    supportTicketSyncPromise = runSupportTicketSync(opts).finally(() => {
        supportTicketSyncPromise = null;
        if (supportTicketSyncRerun) {
            supportTicketSyncRerun = false;
            setImmediate(() => { syncSupportTicketsWithRelay({ pullStatuses: true }).catch(() => {}); });
        }
    });
    return supportTicketSyncPromise;
}
async function runSupportTicketSync({ pullStatuses = true } = {}) {
    const startedAt = Date.now();
    const installationId = getOrCreateInstallationId(readFeatureUnlocks());
    const receiptSettings = readData(FILE_RECEIPT_SETTINGS, DEFAULT_RECEIPT_SETTINGS);
    const storeName = (receiptSettings && receiptSettings.storeName) || null;
    const headers = { 'Content-Type': 'application/json', 'x-relay-key': RELAY_API_KEY };
    const pushed = new Map();
    const failedPermanently = new Set();
    let deskClosedByRelay = false;
    // New tickets are sent ONLY while RELAY says the desk is open.
    const pending = supportDeskCache.open
        ? readData(FILE_AI_SUPPORT_TICKETS, []).filter((t) => !t.relaySynced && !t.relaySyncFailed).slice(0, SUPPORT_TICKET_SYNC_BATCH)
        : [];
    for (const t of pending) {
        if (Date.now() - startedAt > SUPPORT_TICKET_SYNC_DEADLINE_MS) break;
        let relayRes;
        try {
            relayRes = await relayFetch(`${RELAY_URL}/relay/support-tickets`, {
                method: 'POST',
                headers,
                body: JSON.stringify({ installationId, storeName, username: t.username || undefined, ticket: t })
            }, 6000);
        } catch (err) {
            break; // offline / RELAY down: keep everything queued for the next signal
        }
        const data = await relayRes.json().catch(() => null);
        if (relayRes.ok && data && data.success) {
            pushed.set(t.id, data);
        } else if (data && data.code === 'SUPPORT_DESK_CLOSED') {
            deskClosedByRelay = true; // RELAY closed the desk since our last signal
            break;
        } else if (relayRes.status === 400) {
            failedPermanently.add(t.id); // RELAY rejected the content itself; do not retry forever
        } else {
            break; // 403 (device not allowed yet), 429, 5xx: retry on a later signal
        }
    }
    if (deskClosedByRelay) supportDeskCache = { ...supportDeskCache, open: false };

    // Pull statuses/replies only when RELAY reports a change for this
    // installation (updateSeq differs from the last one processed) or right
    // after tickets were pushed. This works even while the desk is closed, so
    // replies that were already written still arrive.
    const syncState = readSupportSyncState();
    const seqNow = String(supportDeskCache.updateSeq || '0');
    const lastSeq = String(syncState.lastSeq === undefined || syncState.lastSeq === null ? '0' : syncState.lastSeq);
    const anySynced = readData(FILE_AI_SUPPORT_TICKETS, []).some((t) => t.relaySynced);
    const shouldPull = pullStatuses && (pushed.size > 0 || (anySynced && seqNow !== lastSeq));
    let statusMap = new Map();
    let pullOk = false;
    let seqFromRelay = null;
    if (shouldPull && Date.now() - startedAt <= SUPPORT_TICKET_SYNC_DEADLINE_MS) {
        try {
            const relayRes = await relayFetch(`${RELAY_URL}/relay/support-tickets/status?installationId=${encodeURIComponent(installationId)}`, { method: 'GET', headers: { 'x-relay-key': RELAY_API_KEY } }, 6000);
            const data = await relayRes.json().catch(() => null);
            if (relayRes.ok && data && data.success && Array.isArray(data.tickets)) {
                statusMap = new Map(data.tickets.map((row) => [String(row.localTicketId), row]));
                seqFromRelay = (data.updateSeq === undefined || data.updateSeq === null) ? null : String(data.updateSeq);
                pullOk = true;
            }
        } catch (err) { /* ignore: statuses just stay as they were */ }
    }
    // Re-read fresh data AFTER the network calls and merge by id, so a ticket
    // created or edited meanwhile is never overwritten.
    const fresh = readData(FILE_AI_SUPPORT_TICKETS, []);
    let changed = false;
    for (const t of fresh) {
        if (pushed.has(t.id) && !t.relaySynced) {
            t.relaySynced = true;
            t.relaySyncedAt = new Date().toISOString();
            changed = true;
        }
        if (failedPermanently.has(t.id) && !t.relaySyncFailed) {
            t.relaySyncFailed = true;
            changed = true;
        }
        if (!t.relaySynced) continue;
        const info = statusMap.get(String(t.id)) || pushed.get(t.id);
        if (!info) continue;
        const nextNote = info.adminNote || '';
        if (t.relayStatus !== info.status || (t.relayNote || '') !== nextNote) {
            t.relayStatus = info.status;
            t.relayNote = nextNote;
            t.relayUpdatedAt = info.updatedAt || new Date().toISOString();
            // When the developer resolves/closes a ticket, mirror it locally
            // so it does not stay "Open" in the store admin's list.
            if ((info.status === 'resolved' || info.status === 'closed') && (t.status === 'open' || t.status === 'in_progress')) {
                t.status = info.status;
                t.updatedAt = t.relayUpdatedAt;
            }
            changed = true;
        }
    }
    if (changed) writeData(FILE_AI_SUPPORT_TICKETS, fresh);
    // Remember the marker RELAY returned WITH the statuses (not the older one
    // from the pricing response), so our own push does not cause an extra pull.
    if (pullOk) writeData(FILE_AI_SUPPORT_SYNC_STATE, { lastSeq: seqFromRelay !== null ? seqFromRelay : seqNow, lastPullAt: new Date().toISOString() });
    return { success: true, pushed: pushed.size, pulled: pullOk };
}
// Called after every RELAY pricing refresh (the existing signal channel).
// Makes no request unless there is something to send (desk open + queued
// tickets) or RELAY reports new activity for this installation.
function onSupportDeskSignal() {
    try {
        if (!RELAY_API_KEY) return;
        const tickets = readData(FILE_AI_SUPPORT_TICKETS, []);
        const st = readSupportSyncState();
        const lastSeq = String(st.lastSeq === undefined || st.lastSeq === null ? '0' : st.lastSeq);
        const needPush = supportDeskCache.open && supportTicketsPendingPush(tickets);
        const needPull = tickets.some((t) => t.relaySynced) && String(supportDeskCache.updateSeq || '0') !== lastSeq;
        if (!needPush && !needPull) return;
        syncSupportTicketsWithRelay({ pullStatuses: true }).catch(() => {});
    } catch (err) { /* never let the signal handler throw */ }
}
app.post('/api/support-tickets', requireFeature('ai_assistant'), rateLimit('support-ticket-create', 5, 15 * 60 * 1000, (retryAfterSec) => `You have reached the support ticket limit. Please try again in ${retryAfterSec} seconds.`), async (req, res) => {
    // Refresh the desk state on demand (throttled to once per minute, 4s max)
    // so a ticket created right after support reopens is sent immediately.
    try { await refreshCloudBackupPricingIfStale(); } catch (_) {}
    const username = (req.authUser && req.authUser.username) || 'Unknown';
    const subject = (typeof req.body?.subject === 'string' ? req.body.subject.trim() : '').slice(0, 150) || 'Omni AI support request';
    const message = (typeof req.body?.message === 'string' ? req.body.message.trim() : '').slice(0, 4000);
    const transcript = Array.isArray(req.body?.transcript)
        ? req.body.transcript.slice(-20).map((t) => ({
            role: t && t.role === 'assistant' ? 'assistant' : 'user',
            text: (typeof t?.text === 'string' ? t.text : '').slice(0, 800)
        })).filter((t) => t.text)
        : [];
    const diagnostics = sanitizeSupportTicketDiagnostics(req.body?.diagnostics);
    if (!message && !transcript.length) {
        return res.status(400).json({ success: false, message: 'Please describe the issue before submitting a ticket.' });
    }
    const tickets = readData(FILE_AI_SUPPORT_TICKETS, []);
    const ticket = {
        id: Date.now(),
        username,
        subject,
        message,
        transcript,
        diagnostics,
        status: 'open',
        createdAt: new Date().toISOString()
    };
    tickets.unshift(ticket);
    writeData(FILE_AI_SUPPORT_TICKETS, tickets.slice(0, AI_ASSISTANT_TICKET_CAP));
    logAction(username, `Created an Omni AI support ticket: "${subject}"`);
    // Best-effort: if the RELAY support desk is open, forward the ticket in
    // the background. Otherwise (desk closed / RELAY unreachable) it stays
    // queued locally and is sent on the next desk-open signal.
    syncSupportTicketsWithRelay({ pullStatuses: false }).catch(() => {});
    res.json({ success: true, ticket, supportDeskOpen: !!supportDeskCache.open, supportDeskMessage: supportDeskCache.message || '' });
});
app.get('/api/support-tickets', async (req, res) => {
    if (!req.authUser || (req.authUser.role || '').toLowerCase() !== 'admin') {
        return res.status(403).json({ success: false, message: 'Admin access required.' });
    }
    // Refresh the desk signal on demand (throttled), then sync only if the
    // desk is open. When it is closed this makes no support request to RELAY.
    try { await refreshCloudBackupPricingIfStale(); } catch (_) {}
    try { await syncSupportTicketsWithRelay({ pullStatuses: true }); } catch (_) {}
    res.json({
        success: true,
        relayConfigured: !!RELAY_API_KEY,
        supportDesk: { open: !!supportDeskCache.open, message: supportDeskCache.message || '' },
        tickets: readData(FILE_AI_SUPPORT_TICKETS, [])
    });
});
app.patch('/api/support-tickets/:id', (req, res) => {
    if (!req.authUser || (req.authUser.role || '').toLowerCase() !== 'admin') {
        return res.status(403).json({ success: false, message: 'Admin access required.' });
    }
    const id = Number(req.params.id);
    const tickets = readData(FILE_AI_SUPPORT_TICKETS, []);
    const idx = tickets.findIndex((t) => t.id === id);
    if (idx === -1) {
        return res.status(404).json({ success: false, message: 'Ticket not found.' });
    }
    const allowedStatuses = ['open', 'in_progress', 'resolved', 'closed'];
    const status = allowedStatuses.includes(req.body?.status) ? req.body.status : tickets[idx].status;
    tickets[idx] = { ...tickets[idx], status, updatedAt: new Date().toISOString() };
    writeData(FILE_AI_SUPPORT_TICKETS, tickets);
    logAction(req.authUser.username, `Updated Omni AI support ticket #${id} to "${status}"`);
    res.json({ success: true, ticket: tickets[idx] });
});
// Manual delete ng support ticket (Admin lang) — puwede kahit tapos na (resolved/closed) o hindi pa.
// Lokal na kopya lang ang binubura: kung naipadala na ito sa RELAY, nananatili ang kopya ng developer doon.
// Kung hindi pa naipadala (naka-queue), hindi na ito ipapadala kapag binura.
app.delete('/api/support-tickets/:id', (req, res) => {
    if (!req.authUser || (req.authUser.role || '').toLowerCase() !== 'admin') {
        return res.status(403).json({ success: false, message: 'Admin access required.' });
    }
    const id = Number(req.params.id);
    if (!Number.isFinite(id)) {
        return res.status(400).json({ success: false, message: 'Invalid ticket id.' });
    }
    const tickets = readData(FILE_AI_SUPPORT_TICKETS, []);
    const target = tickets.find((t) => t.id === id);
    if (!target) {
        return res.status(404).json({ success: false, message: 'Ticket not found.' });
    }
    writeData(FILE_AI_SUPPORT_TICKETS, tickets.filter((t) => t.id !== id));
    logAction(req.authUser.username, `Deleted Omni AI support ticket #${id} ("${String(target.subject || '').slice(0, 80)}", status: ${target.status || 'unknown'})`);
    res.json({ success: true, deletedId: id });
});
async function parseRelayResponse(relayRes) {
    const rawText = await relayRes.text();
    let parsed;
    try {
        parsed = rawText ? JSON.parse(rawText) : {};
    } catch (err) {
        throw new Error(
            `the relay returned an unexpected non-JSON response (HTTP ${relayRes.status}). ` +
            `This usually means the relay service isn't running, RELAY_URL is misconfigured, ` +
            `or the relay crashed and returned an error page instead of JSON.`
        );
    }
    if (!relayRes.ok && parsed.success === undefined) {
        throw new Error(parsed.message || `the relay responded with HTTP ${relayRes.status}.`);
    }
    return parsed;
}
function relayRejectionResponse(res, relayData, fallbackMessage) {
    if (relayData && relayData.deviceNotAllowed) {
        return res.status(403).json({
            success: false,
            pendingAuthorization: true,
            message: 'Naipadala na ang device na ito papuntang developer/store owner para sa authorization. Wala pang access ang device na ito — maghintay lang na ma-\"Allow\" ka sa Relay admin panel, at awtomatiko na itong susubukan ulit.'
        });
    }
    if (relayData && relayData.code === 'DEVELOPER_UNAVAILABLE') {
        return res.status(503).json({ success: false, code: 'DEVELOPER_UNAVAILABLE', message: relayData.message || 'Developer is unavailable at this time.' });
    }
    return res.status(502).json({ success: false, message: (relayData && relayData.message) || fallbackMessage });
}
app.post('/api/features/request-unlock', requirePermission('relay_unlock_request'), rateLimit('feature-unlock-request', 3, 10 * 60 * 1000), async (req, res) => {
    if (!activationFlagsCache.otpRequestsEnabled) {
        return res.status(503).json({ success: false, message: 'Manual unlock requests ("Send Request") are temporarily disabled by the developer. Please try "Activate via Omni Tokens" instead, or try again later.' });
    }
    const { featureId, username, photo, tier, billingCycle } = req.body;
    const feature = FEATURE_CATALOG[featureId];
    if (!feature) {
        return res.status(400).json({ success: false, message:'Unknown feature.' });
    }
    if (!RELAY_API_KEY) {
        return res.status(500).json({ success: false, message:'RELAY_API_KEY is not configured on this server. Please contact the developer.' });
    }
    const isCloudBackup = featureId === CLOUD_BACKUP_FEATURE_ID;
    const isModuleSubscription = isModuleSubscriptionFeature(featureId);
    let aiPlanChoice = null;
    if (featureId === 'ai_assistant' && req.body.aiTierId) {
        aiPlanChoice = resolveAiSubscriptionPlanChoice(req.body.aiTierId, billingCycle);
        if (!aiPlanChoice.ok) return res.status(400).json({ success: false, message: aiPlanChoice.message });
    }
    let resolvedPrice = feature.price;
    if (isCloudBackup) {
        resolvedPrice = getCloudBackupPlanPrice(tier, billingCycle);
        if (!CLOUD_BACKUP_PLANS[tier] || !CLOUD_BACKUP_BILLING_CYCLES[billingCycle] || resolvedPrice === null) {
            return res.status(400).json({ success: false, message: 'Please choose a valid Cloud Backup plan (Basic/Standard/Pro) and billing cycle (Monthly/Yearly).' });
        }
    } else if (isModuleSubscription) {
        resolvedPrice = aiPlanChoice ? aiPlanChoice.price : getModuleSubscriptionPrice(featureId, billingCycle);
        if (!MODULE_SUBSCRIPTION_BILLING_CYCLES[billingCycle] || resolvedPrice === null) {
            return res.status(400).json({ success: false, message: `Please choose a valid billing cycle (Monthly/Yearly) for ${feature.name}.` });
        }
    }
    const data = readFeatureUnlocks();
    const installationId = getOrCreateInstallationId(data);
    const isAnySubscription = isCloudBackup || isModuleSubscription;
    if (!isAnySubscription && data.tokens[featureId] && verifyUnlockToken(data.tokens[featureId], installationId, featureId)) {
        return res.json({ success: true, alreadyUnlocked: true, message: `Naka-unlock na ang ${feature.name}.` });
    }
    try {
        const receiptSettings = readData(FILE_RECEIPT_SETTINGS, DEFAULT_RECEIPT_SETTINGS);
        const relayRes = await relayFetch(`${RELAY_URL}/relay/request-unlock`, {
            method:'POST',
            headers: {'Content-Type':'application/json','x-relay-key': RELAY_API_KEY },
            body: JSON.stringify({
                installationId,
                featureId,
                featureName: isCloudBackup ? CLOUD_BACKUP_PLANS[tier].name : feature.name,
                price: resolvedPrice,
                tier: isCloudBackup ? tier : undefined,
                billingCycle: isAnySubscription ? billingCycle : undefined,
                aiTierId: aiPlanChoice ? aiPlanChoice.aiTierId : undefined,
                username: username ||'Unknown',
                storeName: (receiptSettings && receiptSettings.storeName) || null,
                photo: photo || null
            })
        });
        const relayData = await parseRelayResponse(relayRes);
        if (!relayData.success) {
            return relayRejectionResponse(res, relayData, 'The unlock relay declined the request.');
        }
        logAction(username ||'Unknown', isCloudBackup
            ? `Requested an OTP to subscribe to Cloud Backup (${CLOUD_BACKUP_PLANS[tier].name}, ${CLOUD_BACKUP_BILLING_CYCLES[billingCycle].label}, ₱${resolvedPrice})`
            : isModuleSubscription
                ? `Requested an OTP to subscribe to ${feature.name}${aiPlanChoice && aiPlanChoice.tier ? ' — ' + aiPlanChoice.tier.name : ''} (${MODULE_SUBSCRIPTION_BILLING_CYCLES[billingCycle].label}, ₱${resolvedPrice})`
                : `Requested an OTP to unlock ${feature.name}`);
        res.json({ success: true, message:'The unlock request has been sent. Please wait for the confirmation code from the developer/owner.' });
    } catch (err) {
        console.error('Hindi ma-abot ang Unlock Relay:', err);
        res.status(502).json({ success: false, message: `Could not reach the unlock relay: ${err.message}. Please verify RELAY_URL and your internet connection.` });
    }
});
app.post('/api/features/confirm-unlock', rateLimit('feature-unlock-confirm', 120, 10 * 60 * 1000), async (req, res) => {
    const { featureId, otp, username, tier, billingCycle } = req.body;
    const feature = FEATURE_CATALOG[featureId];
    const isCloudBackup = featureId === CLOUD_BACKUP_FEATURE_ID;
    const isModuleSubscription = isModuleSubscriptionFeature(featureId);
    if (!feature) {
        return res.status(400).json({ success: false, message:'Unknown feature.' });
    }
    if (!otp || !String(otp).trim()) {
        return res.status(400).json({ success: false, message:'The OTP code is required.' });
    }
    if (!RELAY_API_KEY) {
        return res.status(500).json({ success: false, message:'RELAY_API_KEY is not configured on this server. Please contact the developer.' });
    }
    const data = readFeatureUnlocks();
    const installationId = getOrCreateInstallationId(data);
    try {
        const relayRes = await relayFetch(`${RELAY_URL}/relay/confirm-unlock`, {
            method:'POST',
            headers: {'Content-Type':'application/json','x-relay-key': RELAY_API_KEY },
            body: JSON.stringify({ installationId, featureId, otp: String(otp).trim() })
        });
        const relayData = await parseRelayResponse(relayRes);
        if (relayData.pending) {
            return res.status(202).json({ success: false, pending: true, message: relayData.message || 'Tama ang code — naghihintay ng approval ng may-ari.' });
        }
        if (!relayData.success) {
            return res.status(400).json({ success: false, message: relayData.message ||'Failed to verify the code.' });
        }
        if (!verifyUnlockToken(relayData.token, installationId, featureId)) {
            console.error('⚠️ Natanggap ang isang token mula sa relay pero HINDI valid ang signature nito. Posibleng may problema sa RELAY_PUBLIC_KEY_PEM o kompromisado ang koneksyon.');
            return res.status(500).json({ success: false, message:'Hindi valid ang signature ng token na natanggap. Kontakin ang developer.' });
        }
        data.tokens[featureId] = relayData.token;
        if (isCloudBackup) {
            const confirmedTier = (relayData.tier && CLOUD_BACKUP_PLANS[relayData.tier]) ? relayData.tier : tier;
            const confirmedCycle = (relayData.billingCycle && CLOUD_BACKUP_BILLING_CYCLES[relayData.billingCycle]) ? relayData.billingCycle : billingCycle;
            data.cloudBackupPlan = { tier: confirmedTier || null, billingCycle: confirmedCycle || null, activatedAt: Date.now() };
        } else if (isModuleSubscription) {
            const confirmedCycle = (relayData.billingCycle && MODULE_SUBSCRIPTION_BILLING_CYCLES[relayData.billingCycle]) ? relayData.billingCycle : billingCycle;
            data.moduleSubscriptions = data.moduleSubscriptions || {};
            data.moduleSubscriptions[featureId] = { billingCycle: confirmedCycle || null, activatedAt: Date.now() };
        }
        writeData(FILE_FEATURE_UNLOCKS, data);
        logAction(username ||'Unknown', isCloudBackup
            ? `Activated/renewed the Cloud Backup subscription (${data.cloudBackupPlan.tier}/${data.cloudBackupPlan.billingCycle})`
            : isModuleSubscription
                ? `Activated/renewed the ${feature.name} subscription (${data.moduleSubscriptions[featureId].billingCycle})`
                : `Unlocked the feature: ${feature.name}`);
        res.json({ success: true, message: `${feature.name} has been unlocked!`, unlockedFeatureIds: getUnlockedFeatureIds() });
    } catch (err) {
        console.error('Hindi ma-abot ang Unlock Relay:', err);
        res.status(502).json({ success: false, message: `Could not reach the unlock relay: ${err.message}. Please verify RELAY_URL and your internet connection.` });
    }
});
