app.get('/api/product-full/:code', (req, res) => {
    res.set('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    res.set('Pragma', 'no-cache');
    res.set('Expires', '0');
    const wanted = String(req.params.code || '').trim().toLowerCase();
    // Isang product lang ang kailangan: catalog nang walang photo + photo row ng ISANG code lang.
    const products = readProductsNoImages();
    const found = Array.isArray(products)
        ? products.find(p => p && String(p.code || '').trim().toLowerCase() === wanted)
        : null;
    if (!found) {
        return res.status(404).json({ success: false, message: 'Product not found.' });
    }
    const imageEntry = getProductImagesByCodes([found.code])[String(found.code)];
    const product = imageEntry
        ? { ...found, image: imageEntry.image, images: imageEntry.images, imageVer: imageEntry.ver }
        : found;
    res.json({ success: true, product });
});
// Batch na pagkuha ng photo (image + images gallery) para sa mga product code
// na hiningi ng client. Maliit na batch lang bawat request para hindi mabigat.
app.post('/api/products/images', (req, res) => {
    res.set('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    const rawCodes = req.body && Array.isArray(req.body.codes) ? req.body.codes : null;
    if (!rawCodes) {
        return res.status(400).json({ success: false, message: 'codes must be an array.' });
    }
    const codes = rawCodes
        .filter(c => typeof c === 'string' || typeof c === 'number')
        .map(c => String(c))
        .slice(0, 40);
    if (!codes.length) {
        return res.json({ success: true, items: {} });
    }
    const items = getProductImagesByCodes(codes);
    res.json({ success: true, items });
});
app.get('/api/products/export', requirePermission('products'), requireFeature('advanced_reports'), (req, res) => {
    try {
        const products = readProductsNoImages();
        const escapeCsv = (val) => {
            const s = (val === undefined || val === null) ?'' : val.toString();
            return/[",\n]/.test(s) ? `"${s.replace(/"/g,'""')}"` : s;
        };
        const headers = ['Code','Product Name','Category','Price','Wholesale Price','Reseller Price','Stock','Supplier','Expiry Date','Low Stock Threshold','Cost Price'];
        const lines = [headers.join(',')];
        products.forEach(p => {
            const priceLevels = (p && p.priceLevels && typeof p.priceLevels === 'object' && !Array.isArray(p.priceLevels)) ? p.priceLevels : {};
            const getLevelPrice = (wanted) => {
                const key = Object.keys(priceLevels).find(k => String(k).trim().toLowerCase() === wanted);
                return key ? priceLevels[key] : '';
            };
            lines.push([
                escapeCsv(p.code), escapeCsv(p.name), escapeCsv(p.category),
                escapeCsv(p.price), escapeCsv(getLevelPrice('wholesale')), escapeCsv(getLevelPrice('reseller')),
                escapeCsv(p.stock), escapeCsv(p.supplier), escapeCsv(p.expiryDate),
                escapeCsv(p.lowStockThreshold), escapeCsv(p.cost)
            ].join(','));
        });
        const csvContent ='\uFEFF' + lines.join('\r\n');
        res.setHeader('Content-Type','text/csv; charset=utf-8');
        res.setHeader('Content-Disposition', `attachment; filename="inventory_export_${Date.now()}.csv"`);
        res.send(csvContent);
    } catch (err) {
        console.error('Export error:', err);
        res.status(500).json({ success: false, message:'Hindi ma-export ang inventory.' });
    }
});
function csvTemplateEscape(val) {
    const s = (val === undefined || val === null) ? '' : val.toString();
    return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}
