    paymongo: {
        id: 'paymongo',
        name: 'PayMongo',
        testKeyPrefix: 'sk_test_',
        liveKeyPrefix: 'sk_live_',
        dashboardUrl: 'https://dashboard.paymongo.com/developers'
    },
